// Simple in-memory store standing in for a real database / user record.
// In a real app this would be a DB read/write keyed by the authenticated user.
let notificationsEnabled = false

export function getNotificationPreference(): boolean {
  return notificationsEnabled
}

export function setNotificationPreference(value: boolean): void {
  notificationsEnabled = value
}

