'use server'

import { revalidatePath } from 'next/cache'
import {
  getNotificationPreference,
  setNotificationPreference,
} from './preferences'

export async function toggleNotificationPreference() {
  // Flip the stored preference.
  const next = !getNotificationPreference()
  setNotificationPreference(next)

  // Refresh the current page so it re-renders with the updated preference.
  // revalidatePath purges the cached render for this route and triggers a
  // fresh server render on the next request — no redirect / navigation.
  revalidatePath('/')
}

